// account-events-producer.ts
// Producer for the account-events topic (KafkaJS-style client).

import { Kafka, Producer } from "kafkajs";

export interface AccountEvent {
  accountId: string; // real-world entity id, e.g. "acct-123" — must be stable for the entity's whole lifecycle
  schemaVersion: string; // e.g. "v2" — introduced in the same deploy that broke ordering
  payload: Record<string, unknown>;
}

// The deploy also raised the topic's partition count for this topic.
const numPartitions = 24; // was 12 before the deploy

function serialize(event: AccountEvent): Buffer {
  return Buffer.from(JSON.stringify(event));
}

/**
 * Builds the Kafka partition key for an AccountEvent.
 *
 * Kafka routes each record via `partition = hash(key) % numPartitions`,
 * so the key's literal bytes — not its "meaning" to a human — decide
 * which partition an event lands on. FIFO ordering only holds within
 * a single partition.
 */
function buildPartitionKey(event: AccountEvent): string {
  // return event.accountId;
  return `${event.schemaVersion}:${event.accountId}`;
}

export class AccountEventsProducer {
  constructor(private readonly producer: Producer) {}

  async publish(event: AccountEvent): Promise<void> {
    await this.producer.send({
      topic: "account-events",
      messages: [
        {
          key: buildPartitionKey(event),
          value: serialize(event),
        },
      ],
    });
  }
}

// --- test outline -----------------------------------------------------

function hashToPartition(key: string, partitions: number): number {
  let hash = 0;
  for (let i = 0; i < key.length; i++) {
    hash = (hash * 31 + key.charCodeAt(i)) | 0;
  }
  return Math.abs(hash) % partitions;
}

describe("AccountEventsProducer partition routing", () => {
  it("keeps one account's burst on a single partition across a key change", () => {
    const accountId = "acct-123";

    const burst: AccountEvent[] = [
      { accountId, schemaVersion: "v1", payload: { seq: 1 } },
      { accountId, schemaVersion: "v1", payload: { seq: 2 } },
      { accountId, schemaVersion: "v2", payload: { seq: 3 } }, // schema flips mid-burst
      { accountId, schemaVersion: "v2", payload: { seq: 4 } },
    ];

    const partitions = burst.map((event) =>
      hashToPartition(buildPartitionKey(event), numPartitions),
    );

    const [firstPartition, ...rest] = partitions;
    expect(rest.every((partition) => partition === firstPartition)).toBe(true);
  });
});
